using System.Collections.Generic;
using System.Linq;

public class Cache
{
    private class Entry
    {
        public int Value;
        public long StoredAt;
    }

    private readonly int _capacity;
    private readonly long _ttl;
    private readonly Dictionary<string, Entry> _store = new();
    private readonly List<string> _order = new(); // front = most recently used

    public Cache(int capacity, long ttl)
    {
        _capacity = capacity;
        _ttl = ttl;
    }

    private void Touch(string key)
    {
        _order.Remove(key);
        _order.Insert(0, key);
    }

    public void Put(string key, int value, long now)
    {
        if (!_store.ContainsKey(key) && _store.Count >= _capacity)
        {
            var oldest = _order[^1];
            _order.RemoveAt(_order.Count - 1);
            _store.Remove(oldest);
        }
        _store[key] = new Entry { Value = value, StoredAt = now };
        Touch(key);
    }

    public int? Get(string key, long now)
    {
        if (!_store.TryGetValue(key, out var entry))
        {
            return null;
        }
        if (now - entry.StoredAt >= _ttl)
        {
            _store.Remove(key);
            _order.Remove(key);
            return null;
        }
        Touch(key);
        return entry.Value;
    }
}

