using Xunit;

public class CacheTests
{
    [Fact]
    public void CapacityEvictsLeastRecentlyUsed()
    {
        var c = new Cache(2, 1000);
        c.Put("a", 1, 0);
        c.Put("b", 2, 1);
        c.Get("a", 2);
        c.Put("c", 3, 3);
        Assert.Equal(1, c.Get("a", 4));
        Assert.Null(c.Get("b", 4));
        Assert.Equal(3, c.Get("c", 4));
    }

    [Fact]
    public void GetRefreshesRecency()
    {
        var c = new Cache(2, 1000);
        c.Put("a", 1, 0);
        c.Put("b", 2, 1);
        c.Get("a", 2);
        c.Get("b", 3);
        c.Put("c", 3, 4);
        Assert.Null(c.Get("a", 5));
        Assert.Equal(2, c.Get("b", 5));
    }

    [Fact]
    public void TtlExpiryIndependentOfCapacity()
    {
        var c = new Cache(5, 10);
        c.Put("a", 1, 0);
        Assert.Equal(1, c.Get("a", 9));
        Assert.Null(c.Get("a", 10));
    }
}
